package com.example.signlearn

import android.content.Context
import android.graphics.Canvas
import android.graphics.Paint
import android.graphics.Path
import android.graphics.RectF
import android.util.AttributeSet
import android.view.View
import androidx.core.content.ContextCompat
import kotlin.math.atan2
import kotlin.math.cos
import kotlin.math.min
import kotlin.math.sin

/**
 * Draws a friendly cartoon hand for a sign (letters A–Z and the word signs).
 * The shapes come from HandShapes.kt (generated by tools/hands.py).
 */
class HandSignView @JvmOverloads constructor(
    context: Context, attrs: AttributeSet? = null
) : View(context, attrs) {

    private var data: FloatArray? = null
    var signKey: String = ""
        private set

    private val fillPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply { style = Paint.Style.FILL }
    private val strokePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        style = Paint.Style.STROKE
        strokeCap = Paint.Cap.ROUND
        strokeJoin = Paint.Join.ROUND
    }
    private val path = Path()
    private val bounds = RectF()

    private val skin = ContextCompat.getColor(context, R.color.skin)
    private val skinShade = ContextCompat.getColor(context, R.color.skin_shade)
    private val line = ContextCompat.getColor(context, R.color.skin_line)
    private val arrow = ContextCompat.getColor(context, R.color.primary)

    fun setSign(key: String) {
        signKey = key
        data = HandShapes.get(key)
        computeBounds()
        invalidate()
    }

    private fun computeBounds() {
        // Always include the normal drawing box so upright hands share the same size,
        // and grow it for rotated hands (G, H, P, Q) so they still fit.
        bounds.set(2f, 0f, 98f, 124f)
        val d = data ?: return
        var i = 0
        while (i < d.size) {
            val n = d[i + 2].toInt()
            var k = 0
            while (k < n) {
                val x = d[i + 3 + k * 2]
                val y = d[i + 4 + k * 2]
                bounds.union(x - 7f, y - 7f, x + 7f, y + 7f)
                k++
            }
            i += 3 + n * 2
        }
    }

    override fun onDraw(canvas: Canvas) {
        super.onDraw(canvas)
        val d = data ?: return
        val availW = (width - paddingLeft - paddingRight).toFloat()
        val availH = (height - paddingTop - paddingBottom).toFloat()
        if (availW <= 0 || availH <= 0) return
        val s = min(availW / bounds.width(), availH / bounds.height())
        val ox = paddingLeft + (availW - bounds.width() * s) / 2f - bounds.left * s
        val oy = paddingTop + (availH - bounds.height() * s) / 2f - bounds.top * s

        var i = 0
        while (i < d.size) {
            val type = d[i].toInt()
            val w = d[i + 1]
            val n = d[i + 2].toInt()
            path.reset()
            for (k in 0 until n) {
                val x = ox + d[i + 3 + k * 2] * s
                val y = oy + d[i + 4 + k * 2] * s
                if (k == 0) path.moveTo(x, y) else path.lineTo(x, y)
            }
            when (type) {
                0 -> { // palm
                    path.close()
                    fillPaint.color = skin
                    canvas.drawPath(path, fillPaint)
                    strokePaint.color = line
                    strokePaint.strokeWidth = 2.6f * s
                    canvas.drawPath(path, strokePaint)
                }
                1, 3 -> { // finger / thumb capsule: outline first, then fill
                    strokePaint.color = line
                    strokePaint.strokeWidth = (w + 2.6f) * s
                    canvas.drawPath(path, strokePaint)
                    strokePaint.color = if (type == 3) skinShade else skin
                    strokePaint.strokeWidth = w * s
                    canvas.drawPath(path, strokePaint)
                }
                2 -> { // motion arrow
                    strokePaint.color = arrow
                    strokePaint.strokeWidth = w * s
                    canvas.drawPath(path, strokePaint)
                    if (n >= 2) {
                        val x2 = ox + d[i + 3 + (n - 1) * 2] * s
                        val y2 = oy + d[i + 4 + (n - 1) * 2] * s
                        val x1 = ox + d[i + 3 + (n - 2) * 2] * s
                        val y1 = oy + d[i + 4 + (n - 2) * 2] * s
                        val a = atan2(y2 - y1, x2 - x1)
                        val len = 7f * s
                        path.reset()
                        path.moveTo(x2 + cos(a) * 2f * s, y2 + sin(a) * 2f * s)
                        path.lineTo(x2 - len * cos(a - 0.5f), y2 - len * sin(a - 0.5f))
                        path.lineTo(x2 - len * cos(a + 0.5f), y2 - len * sin(a + 0.5f))
                        path.close()
                        fillPaint.color = arrow
                        canvas.drawPath(path, fillPaint)
                    }
                }
            }
            i += 3 + n * 2
        }
    }
}
